package com.sisge.ms.entity; import jakarta.persistence.*;
@Entity @Table(name="auditoria_cambios") public class AuditoriaCambio { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="evento_id") private AuditoriaEvento evento; @Column(name="valor_anterior",columnDefinition="TEXT") private String valorAnterior; @Column(name="valor_nuevo",columnDefinition="TEXT") private String valorNuevo; public void setEvento(AuditoriaEvento v){evento=v;} public void setValorAnterior(String v){valorAnterior=v;} public void setValorNuevo(String v){valorNuevo=v;} }
